<script setup>
import {onMounted,ref} from 'vue'
import {getReadyForAssignment,getActiveCouriers,assignCourier} from '../services/api'
const props=defineProps({user:{type:Object,required:true},token:{type:String,required:true}})
const emit=defineEmits(['logout'])
const orders=ref([]),couriers=ref([]),selected=ref(null),courierId=ref(''),loading=ref(false),busy=ref(false),error=ref(''),success=ref('')
const displayName=[props.user.first_name,props.user.first_surname].filter(Boolean).join(' ')||'Administrador'
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v||0))
async function load(){loading.value=true;error.value='';try{[orders.value,couriers.value]=await Promise.all([getReadyForAssignment(props.token),getActiveCouriers(props.token)])}catch(e){error.value=e.message||'No fue posible cargar los pedidos para asignación.'}finally{loading.value=false}}
async function assign(){if(!selected.value||!courierId.value)return;busy.value=true;error.value='';success.value='';try{await assignCourier(selected.value.id,Number(courierId.value),props.token);success.value=`Domiciliario asignado al pedido #${selected.value.id}.`;selected.value=null;courierId.value='';await load()}catch(e){error.value=e.message||'No fue posible asignar el domiciliario.'}finally{busy.value=false}}
onMounted(load)
</script>
<template><main class="operations-shell"><header class="operations-header"><a class="customer-brand" href="#" @click.prevent="load"><span class="customer-brand-mark">♧</span><span><strong>Canasta Express</strong><small>Legumbrería &amp; Verdulería Online</small></span></a><div class="operations-user"><span>Hola, {{displayName}}</span><button @click="emit('logout')">Salir</button></div></header><section class="operations-page"><div class="operations-title-row"><div><p class="operations-kicker">ADMINISTRACIÓN · DESPACHOS</p><h1>Asignación de domiciliarios</h1><p>Asigna los pedidos empacados a un domiciliario activo para iniciar su entrega.</p></div><button class="operations-refresh" @click="load">↻ Actualizar</button></div><p v-if="error" class="operations-alert error">{{error}}</p><p v-if="success" class="operations-alert success">{{success}}</p><div v-if="loading" class="operations-empty">Cargando pedidos…</div><div v-else-if="orders.length" class="assignment-grid"><button v-for="order in orders" :key="order.id" class="assignment-card" :class="{selected:selected?.id===order.id}" @click="selected=order;courierId=''"><span class="operations-status">Empacado</span><h2>Pedido #{{order.id}}</h2><p>{{order.customer_name}}</p><p>{{order.shipping_neighborhood}}, {{order.shipping_city}}</p><strong>{{money(order.total_price)}}</strong></button></div><div v-else class="operations-empty">No hay pedidos empacados pendientes de asignación.</div><section v-if="selected" class="assignment-form"><h2>Asignar pedido #{{selected.id}}</h2><label class="customer-field">Domiciliario<select v-model="courierId"><option value="" disabled>Selecciona un domiciliario</option><option v-for="courier in couriers" :key="courier.id" :value="String(courier.id)">{{courier.first_name}} {{courier.first_surname}}</option></select></label><button class="operations-primary" :disabled="busy||!courierId" @click="assign">{{busy?'Asignando…':'Confirmar asignación'}}</button></section></section></main></template>